using LMS_BE.Data;using LMS_BE.Models;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Authorization;using Microsoft.EntityFrameworkCore;
namespace LMS_BE.Controllers;
[Route("api/learning-path")]
public class LearningPathController(ApplicationDbContext db):LmsControllerBase(db){
 [HttpGet("me")]public async Task<IActionResult> Mine()=>Ok(await Db.LearningPaths.Where(p=>p.StudentId==CurrentUserId).OrderByDescending(p=>p.GeneratedAt).Select(p=>new{p.Id,p.CourseId,Course=p.Course!.CourseName,p.GeneratedAt,p.Status,p.Explanation,Items=p.Items.OrderBy(i=>i.SequenceNo).Select(i=>new{i.Id,i.LessonId,Lesson=i.Lesson!.Title,i.SequenceNo,i.PriorityScore,i.Status})}).ToListAsync());
 [HttpPost("generate/{courseId:guid}")][Authorize(Roles="Student")]public async Task<IActionResult> Generate(Guid courseId){if(!await Db.Enrollments.AnyAsync(e=>e.StudentId==CurrentUserId&&e.Class!.CourseId==courseId))return Forbid();var lessons=await Db.Lessons.Include(l=>l.Module).Where(l=>l.Module!.CourseId==courseId).OrderBy(l=>l.Module!.SequenceNo).ThenBy(l=>l.SequenceNo).ToListAsync();if(lessons.Count==0)return BadRequest("Course has no lessons");var viewed=await Db.LearningActivities.Where(a=>a.StudentId==CurrentUserId&&a.LessonId.HasValue).Select(a=>a.LessonId!.Value).Distinct().ToListAsync();var p=new LearningPath{StudentId=CurrentUserId,CourseId=courseId,Explanation="Baseline recommendation: prioritize lessons not yet accessed, then course order."};var ordered=lessons.OrderBy(l=>viewed.Contains(l.Id)?1:0).ThenBy(l=>l.Module!.SequenceNo).ThenBy(l=>l.SequenceNo).ToList();for(int i=0;i<ordered.Count;i++)p.Items.Add(new LearningPathItem{LessonId=ordered[i].Id,SequenceNo=i+1,PriorityScore=viewed.Contains(ordered[i].Id)?0.25m:1m});Db.LearningPaths.Add(p);await Db.SaveChangesAsync();return Ok(new{p.Id,Items=p.Items.Count,p.Explanation});}
 [HttpPut("items/{id:guid}/complete")][Authorize(Roles="Student")]public async Task<IActionResult> Complete(Guid id){var i=await Db.LearningPathItems.Include(i=>i.Path).FirstOrDefaultAsync(i=>i.Id==id);if(i==null)return NotFound();if(i.Path!.StudentId!=CurrentUserId)return Forbid();i.Status="Completed";await Db.SaveChangesAsync();return NoContent();}
}
